 <div x-show="showPaymentModal" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm" style="display: none;"><div class="w-full max-w-4xl overflow-hidden rounded-xl bg-white shadow-2xl" @click.away="showPaymentModal=false"><div class="flex items-center justify-between border-b border-slate-100 px-6 py-4"><h2 class="text-xl font-medium text-slate-700">Payment</h2><button type="button" @click="showPaymentModal=false" class="text-slate-400 hover:text-slate-600">✕</button></div><div class="flex"><div class="flex-1 p-6"><div class="mb-4 text-sm font-semibold text-slate-700">Advance Balance: Rs 0.00</div><div class="mb-6 rounded-xl bg-slate-100 p-4"><template x-for="(row, i) in paymentRows" :key="i"><div class="mb-4 flex gap-4"><div class="flex-1"><label class="mb-1 block text-sm font-bold">Amount:*</label><div class="relative"><span class="absolute left-3 top-2.5 text-slate-500">💵</span><input type="number" step="0.01" class="w-full pl-10" x-model.number="row.amount" placeholder="0.00" required></div></div><div class="flex-1"><label class="mb-1 block text-sm font-bold">Payment Method:*</label><div class="relative"><span class="absolute left-3 top-2.5 text-slate-500">💵</span><select class="w-full pl-10" x-model="row.method_id" required><option value="">Select Method</option>@foreach($methods as $m)@if($m->code!=='credit_due')<option value="{{ $m->id }}">{{ $m->name }}</option>@endif @endforeach</select></div></div></div><div class="mb-4"><label class="mb-1 block text-sm font-bold">Payment note:</label><textarea class="w-full" rows="3" x-model="row.note"></textarea></div><div x-show="paymentRows.length > 1" class="mb-4 text-right"><button type="button" @click="paymentRows.splice(i,1)" class="text-sm font-bold text-red-500 hover:underline">Remove Row</button></div><hr class="my-4 border-slate-200" x-show="i < paymentRows.length - 1"></template><button type="button" @click="paymentRows.push({amount:0, method_id:'', note:''})" class="w-full rounded-lg bg-indigo-500 py-2.5 font-bold text-white transition hover:bg-indigo-600">Add Payment Row</button></div><div class="flex gap-4"><div class="flex-1"><label class="mb-1 block text-sm font-bold">Sell note:</label><textarea class="w-full" rows="4" name="sell_note" x-model="sellNote" placeholder="Sell note"></textarea></div><div class="flex-1"><label class="mb-1 block text-sm font-bold">Staff note:</label><textarea class="w-full" rows="4" name="staff_note" x-model="staffNote" placeholder="Staff note"></textarea></div></div></div><div class="w-64 bg-[#ff851b] p-6 text-white"><div class="mb-6"><div class="text-sm font-medium opacity-90">Total Items:</div><div class="text-2xl font-bold" x-text="cart.length.toFixed(2)"></div><div class="mt-4 border-b border-white/20"></div></div><div class="mb-6"><div class="text-sm font-medium opacity-90">Total Payable:</div><div class="text-2xl font-bold">Rs <span x-text="money(total)"></span></div><div class="mt-4 border-b border-white/20"></div></div><div class="mb-6"><div class="text-sm font-medium opacity-90">Total Paying:</div><div class="text-2xl font-bold">Rs <span x-text="money(totalPaying)"></span></div><div class="mt-4 border-b border-white/20"></div></div><div class="mb-6"><div class="text-sm font-medium opacity-90">Change Return:</div><div class="text-2xl font-bold">Rs <span x-text="money(changeReturn)"></span></div><div class="mt-4 border-b border-white/20"></div></div><div><div class="text-sm font-medium opacity-90">Balance:</div><div class="text-2xl font-bold">Rs <span x-text="money(balance)"></span></div></div></div></div><div class="flex justify-end gap-2 border-t border-slate-100 bg-white p-4"><button type="button" @click="showPaymentModal=false" class="rounded-lg bg-slate-700 px-6 py-2.5 font-bold text-white transition hover:bg-slate-800">Close</button><button type="button" @click="submitSale()" class="rounded-lg bg-indigo-500 px-6 py-2.5 font-bold text-white transition hover:bg-indigo-600" :disabled="submitting"><span x-text="submitting?'Processing...':'Finalize Payment'"></span></button></div></div></div>
 
 <form id="checkout-form" method="post" action="{{ route('pos.checkout') }}" style="display:none;">@csrf<input type="hidden" name="sale_type" value="{{ $type }}"><input type="hidden" name="store_id" value="{{ $store->id }}"><input type="hidden" name="idempotency_key" :value="token"><input type="hidden" name="customer_id" :value="customer"><input type="hidden" name="notes" :value="sellNote"><input type="hidden" name="staff_note" :value="staffNote"></form>
</div>
@push('scripts')<script>function pos(catalog,type){return{catalog,type,search:'',category:'',cart:[],customer:'',token:'{{ \Illuminate\Support\Str::uuid() }}',submitting:false,showPaymentModal:false,paymentRows:[],sellNote:'',staffNote:'',get filtered(){let s=this.search.toLowerCase();return this.catalog.filter(x=>(!this.category||String(x.category_id)===this.category)&&(!s||`${x.name} ${x.sku} ${x.barcode||''} ${x.remnant_no||''} ${x.colour||''}`.toLowerCase().includes(s)))},addFirst(){if(this.filtered[0])this.add(this.filtered[0])},available(item,u){return u?Number(item.stock/u.rate).toFixed(3):0},add(item){let u=item.units[0];if(!u)return;let key=item.key+'-'+u.unit_id,found=this.cart.find(x=>x.lineKey===key);if(found&&type==='main'){found.quantity+=1;return}this.cart.push({...item,lineKey:key,unit_id:u.unit_id,quantity:type==='remnant'?item.display_qty:1,price:u.price,discount:0,maxDisplay:Number(item.stock/u.rate).toFixed(6)})},unitChanged(line){let u=line.units.find(x=>x.unit_id==line.unit_id);line.price=u.price;line.maxDisplay=Number(item.stock/u.rate).toFixed(6);line.lineKey=line.key+'-'+u.unit_id},lineTotal(l){return Math.max(0,(Number(l.quantity)||0)*(Number(l.price)||0)-(Number(l.discount)||0))},get subtotal(){return this.cart.reduce((s,l)=>s+(Number(l.quantity)||0)*(Number(l.price)||0),0)},get discount(){return this.cart.reduce((s,l)=>s+(Number(l.discount)||0),0)},get total(){return Math.max(0,this.subtotal-this.discount)},get totalPaying(){return this.paymentRows.reduce((s,r)=>s+(Number(r.amount)||0),0)},get changeReturn(){return Math.max(0,this.totalPaying-this.total)},get balance(){return Math.max(0,this.total-this.totalPaying)},money(v){return Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})},openPaymentModal(){if(this.cart.length===0)return;this.paymentRows=[{amount:this.total,method_id:{{ $methods->firstWhere('code','cash')?->id ?? '""' }},note:''}];this.showPaymentModal=true;},duePay(){if(this.cart.length===0)return;if(!this.customer){alert("Please select a customer for a credit/due sale.");return;}this.paymentRows=[];this.submitSale();},quickPay(){if(this.cart.length===0)return;this.paymentRows=[{amount:this.total,method_id:{{ $methods->firstWhere('code','cash')?->id ?? '""' }},note:''}];this.submitSale();},handleKey(e){if(this.showPaymentModal)return;if(e.key==='F4'){e.preventDefault();this.openPaymentModal();}if(e.key==='F10'){e.preventDefault();this.quickPay();}},submitSale(){if(this.cart.length===0)return;if(this.paymentRows.length && this.paymentRows.some(r=>!r.method_id)){alert("Please select a payment method for all rows.");return;}this.submitting=true;let form=document.getElementById('checkout-form');this.cart.forEach((c,i)=>{form.insertAdjacentHTML('beforeend',`<input type="hidden" name="items[${i}][product_id]" value="${c.product_id}">`);if(c.remnant_id)form.insertAdjacentHTML('beforeend',`<input type="hidden" name="items[${i}][remnant_id]" value="${c.remnant_id}">`);form.insertAdjacentHTML('beforeend',`<input type="hidden" name="items[${i}][unit_id]" value="${c.unit_id}"><input type="hidden" name="items[${i}][quantity]" value="${c.quantity||0}"><input type="hidden" name="items[${i}][unit_price]" value="${c.price||0}"><input type="hidden" name="items[${i}][discount_amount]" value="${c.discount||0}">`)});this.paymentRows.forEach((r,i)=>{form.insertAdjacentHTML('beforeend',`<input type="hidden" name="payments[${i}][payment_method_id]" value="${r.method_id}"><input type="hidden" name="payments[${i}][amount]" value="${r.amount||0}"><input type="hidden" name="payments[${i}][reference]" value="${r.note||''}">`)});form.submit();}}}</script>@endpush @endsection
